def seed_editorial_sections(apps, schema_editor):
    database = schema_editor.connection.alias
    sections = apps.get_model("website", "SiteSection").objects.using(database)
    for key, (title, title_en, subtitle, subtitle_en, content, content_en) in SECTIONS.items():
        sections.get_or_create(key=key, defaults={
            "title": title, "title_en": title_en, "subtitle": subtitle,
            "subtitle_en": subtitle_en, "content": content, "content_en": content_en,
        })

    principles = apps.get_model("website", "PhilosophyFeature").objects.using(database)
    if not principles.exists():
        for order, (title, title_en, body, body_en) in enumerate(PRINCIPLES, start=1):
            principles.create(title=title, title_en=title_en, description=body,
                              description_en=body_en, icon_glyph="", order=order)


